import postgres from 'npm:postgres@3.4.9';
import {createFoundationGateway} from '../../gateway/gateway-core-v1.mjs';
import {createIdentityClaimService} from '../../gateway/identity-claim-v1.mjs';
import {createGrantConsentService} from '../../gateway/grant-consent-v1.mjs';
import {createGrantRevocationService} from '../../gateway/grant-revocation-v1.mjs';
import {createRevocationFeedService} from '../../gateway/revocation-feed-v1.mjs';
import {createRevocationAckService} from '../../gateway/revocation-ack-v1.mjs';
import {createRevocationHealthService} from '../../gateway/revocation-health-v1.mjs';
import {createAppOperationalStatusService} from '../../gateway/app-operational-status-v1.mjs';
import {createCapabilityDiscoveryService} from '../../gateway/capability-discovery-v1.mjs';
import {createIntegrationClientStatusService} from '../../gateway/integration-client-status-v1.mjs';
import {createIntegrationLinkConsentService,createIntegrationCapabilityConsentService,createIntegrationGrantRevocationService,createIntegrationLinkRevocationService,createIntegrationGrantListService} from '../../gateway/integration-user-consent-v1.mjs';
import {createConciergePlanService,createConciergeExecuteService,createConciergeSupersedeService} from '../../gateway/concierge-orchestration-v1.mjs';
import {createIntegrationLinkRequestService,createIntegrationLinkApprovalService,createIntegrationLinkStatusService,createIntegrationLinkExchangeService,createIntegrationLinkPreviewService} from '../../gateway/integration-device-link-v1.mjs';
import {createCapabilityTicketRedeemService} from '../../gateway/capability-ticket-redeem-v2.mjs';
import {createIntegrationDelegationRefreshService} from '../../gateway/integration-delegation-refresh-v1.mjs';
import {createConnectedIntegrationListService,createUserGrantRevocationService,createUserLinkRevocationService,createUserAccessHistoryService,createUserAccessExplanationService,createUserConciergeCancellationService,createUserConciergeJobsService} from '../../gateway/user-integration-controls-v1.mjs';
import {createConciergeRetryService} from '../../gateway/concierge-retry-v1.mjs';
import {createConciergeFleetStatusService} from '../../gateway/concierge-fleet-status-v1.mjs';
import {createFoundationHttpHandler} from '../../gateway/http-handler-v1.mjs';
import {createPublicDefenceStatusService} from '../../gateway/defence-status-v1.mjs';
import {createIntegrationContextPublishService} from '../../gateway/integration-context-publish-v1.mjs';
import {createAtlasFeedPublisherAdmissionService} from '../../../atlas-feed/gateway/publisher-admission-v1.mjs';
import {createAtlasFeedPublishService} from '../../../atlas-feed/gateway/publish-v1.mjs';
import {createSupabaseRuntimeAdapters} from '../supabase-runtime-adapters-v1.mjs';
import {createFoundationRuntimeDefenceGateV1} from '../runtime-defence-gate-v1.mjs';
import defenceLedger from '../../../security/shine-defence/ecosystem-profile-ledger-v1.json' with {type:'json'};
import defenceRevocations from '../../../security/shine-defence/revocations-v1.json' with {type:'json'};

const requireEnv=(name:string)=>{
  const value=Deno.env.get(name);
  if(!value) throw new Error('Missing required environment variable: '+name);
  return value;
};

const rawSql=postgres(requireEnv('SUPABASE_DB_URL'),{
  max:1,
  prepare:false,
  idle_timeout:20,
  connect_timeout:10
});

const sql:any=(strings:any,...values:any[])=>rawSql.begin(async(tx:any)=>{
  await tx.unsafe('set local role foundation_gateway');
  return tx(strings,...values);
});

const adapters=createSupabaseRuntimeAdapters({
  sql,
  fetchImpl:fetch,
  defenceGate:createFoundationRuntimeDefenceGateV1()
});

const gateway=createFoundationGateway({adapters} as any);
const identityClaim=createIdentityClaimService({adapters} as any);
const grantConsent=createGrantConsentService({adapters} as any);
const grantRevocation=createGrantRevocationService({adapters} as any);
const revocationFeed=createRevocationFeedService({adapters} as any);
const revocationAck=createRevocationAckService({adapters} as any);
const revocationHealth=createRevocationHealthService({adapters} as any);
const appOperationalStatus=createAppOperationalStatusService({adapters} as any);
const capabilityDiscovery=createCapabilityDiscoveryService({adapters} as any);
const integrationClientStatus=createIntegrationClientStatusService({adapters} as any);
const integrationLinkConsent=createIntegrationLinkConsentService({adapters} as any);
const integrationCapabilityConsent=createIntegrationCapabilityConsentService({adapters} as any);
const integrationGrantRevocation=createIntegrationGrantRevocationService({adapters} as any);
const integrationLinkRevocation=createIntegrationLinkRevocationService({adapters} as any);
const integrationGrantList=createIntegrationGrantListService({adapters} as any);
const conciergePlan=createConciergePlanService({adapters} as any);
const conciergeExecute=createConciergeExecuteService({adapters} as any);
const conciergeSupersede=createConciergeSupersedeService({adapters} as any);
const integrationLinkRequest=createIntegrationLinkRequestService({adapters} as any);
const integrationLinkApproval=createIntegrationLinkApprovalService({adapters} as any);
const integrationLinkStatus=createIntegrationLinkStatusService({adapters} as any);
const integrationLinkExchange=createIntegrationLinkExchangeService({adapters} as any);
const integrationLinkPreview=createIntegrationLinkPreviewService({adapters} as any);
const capabilityTicketRedeem=createCapabilityTicketRedeemService({adapters} as any);
const integrationDelegationRefresh=createIntegrationDelegationRefreshService({adapters} as any);
const connectedIntegrationList=createConnectedIntegrationListService({adapters} as any);
const userIntegrationGrantRevocation=createUserGrantRevocationService({adapters} as any);
const userIntegrationLinkRevocation=createUserLinkRevocationService({adapters} as any);
const userAccessHistory=createUserAccessHistoryService({adapters} as any);
const userAccessExplanation=createUserAccessExplanationService({adapters} as any);
const userConciergeCancellation=createUserConciergeCancellationService({adapters} as any);
const userConciergeJobs=createUserConciergeJobsService({adapters} as any);
const conciergeRetry=createConciergeRetryService({adapters} as any);
const conciergeFleetStatus=createConciergeFleetStatusService({adapters} as any);
const integrationContextPublish=createIntegrationContextPublishService({adapters} as any);
const atlasFeedPublisherAdmission=createAtlasFeedPublisherAdmissionService({adapters} as any);
const atlasFeedPublish=createAtlasFeedPublishService({publisherAdmission:atlasFeedPublisherAdmission,adapters} as any);
const defenceStatus=createPublicDefenceStatusService({
  ledger:defenceLedger,
  revocations:defenceRevocations
});

const handler=createFoundationHttpHandler({
  gateway,
  identityClaim,
  grantConsent,
  grantRevocation,
  revocationFeed,
  revocationAck,
  revocationHealth,
  appOperationalStatus,
  capabilityDiscovery,
  integrationClientStatus,
  integrationLinkConsent,
  integrationCapabilityConsent,
  integrationGrantRevocation,
  integrationLinkRevocation,
  integrationGrantList,
  conciergePlan,
  conciergeExecute,
  conciergeSupersede,
  integrationLinkRequest,
  integrationLinkApproval,
  integrationLinkStatus,
  integrationLinkExchange,
  integrationLinkPreview,
  capabilityTicketRedeem,
  integrationDelegationRefresh,
  connectedIntegrationList,
  userIntegrationGrantRevocation,
  userIntegrationLinkRevocation,
  userAccessHistory,
  userAccessExplanation,
  userConciergeCancellation,
  userConciergeJobs,
  conciergeRetry,
  conciergeFleetStatus,
  integrationContextPublish,
  atlasFeedPublisherAdmission,
  atlasFeedPublish,
  defenceStatus,
  evaluateOperationPolicy:adapters.evaluateGatewayRoutePolicy,
  operationPolicyRequired:true,
  recordOperationAudit:adapters.recordGatewayOperationAuditEvent,
  operationAuditRequired:true,
  maxBodyBytes:16*1024,
  authenticateIntegrationUser:async(request:Request)=>{
    const authorization=request.headers.get('authorization')??'';
    const jwt=authorization.startsWith('Bearer ')?authorization.slice('Bearer '.length):'';
    if(!jwt) throw new Error('missing integration user credential');
    return {jwt};
  },
  authenticateIntegrationUserAndClient:async(request:Request)=>{
    const authorization=request.headers.get('authorization')??'';
    const clientToken=request.headers.get('x-shine-client-token')??'';
    const delegationToken=request.headers.get('x-shine-delegation-token')??'';
    const jwt=authorization.startsWith('Bearer ')?authorization.slice('Bearer '.length):'';
    if(!clientToken||(!jwt&&!delegationToken)) throw new Error('missing integration actor credentials');
    return {clientToken,...(jwt?{jwt}:{}),...(delegationToken?{delegationToken}:{})};
  },
  authenticateIntegrationClient:async(request:Request)=>{
    const clientToken=request.headers.get('x-shine-client-token')??'';
    const refreshToken=request.headers.get('x-shine-refresh-token')??'';
    if(!clientToken) throw new Error('missing integration client credential');
    return {clientToken,...(refreshToken?{refreshToken}:{})};
  },
  authenticateApp:async(request:Request)=>{
    const appToken=request.headers.get('x-shine-app-token')??'';
    if(!appToken) throw new Error('missing app credential');
    return {appToken};
  },
  authenticate:async(request:Request)=>{
    const authorization=request.headers.get('authorization')??'';
    const appToken=request.headers.get('x-shine-app-token')??'';
    const userToken=request.headers.get('x-shine-user-token')??'';
    const jwt=authorization.startsWith('Bearer ')?authorization.slice('Bearer '.length):'';
    if(!appToken||(!jwt&&!userToken)){
      throw new Error('missing runtime credentials');
    }
    return {appToken,...(jwt?{jwt}:{}),...(userToken?{userToken}:{})};
  },
  authenticateIdentityClaim:async(request:Request)=>{
    const authorization=request.headers.get('authorization')??'';
    const appToken=request.headers.get('x-shine-app-token')??'';
    const sourceUserToken=request.headers.get('x-shine-user-token')??'';
    const targetJwt=authorization.startsWith('Bearer ')?authorization.slice('Bearer '.length):'';
    if(!appToken||!sourceUserToken||!targetJwt){
      throw new Error('missing identity claim credentials');
    }
    return {appToken,sourceUserToken,targetJwt};
  }
} as any);

Deno.serve((request:Request)=>handler(request));

import {
  evaluateAccess,
  appManifestDeclaresPermission
} from '../integration-kit/permission-engine-v1.mjs';

const RESPONSE_VERSION='1.0.0';
const requestVersion=envelope=>{
  if(envelope?.gatewayRequest==='shine-foundation/gateway-request-v1' && envelope?.schemaVersion==='1.0.0') return 1;
  if(envelope?.gatewayRequest==='shine-foundation/gateway-request-v2' && envelope?.schemaVersion==='2.0.0') return 2;
  return 0;
};

const response=(envelope,status,reasonCode,decision)=>({
  gatewayResponse:'shine-foundation/gateway-response-v1',
  schemaVersion:RESPONSE_VERSION,
  traceId:envelope?.traceId??null,
  requestId:envelope?.permission?.requestId??null,
  status,
  ...(reasonCode?{reasonCode}:{}),
  ...(decision?{decision}:{})
});

const requireFunction=(adapters,name)=>{
  if(typeof adapters?.[name]!=='function') throw new TypeError('missing gateway adapter: '+name);
};

const isEnvelopeValid=envelope=>{
  const v=requestVersion(envelope);
  if(!v || envelope.operation!=='access.evaluate' || !envelope.traceId) return false;
  const p=envelope.permission;
  if(!p || !p.requestId || !p.appId || !p.scope || !p.purpose || !p.requestedAt) return false;
  if(v===1 && !p.shineId) return false;
  return Boolean(p.resourceId||p.resourceCategory);
};

const toAuditEvent=({envelope,decision,defenceEvidenceRef,occurredAt,shineId,requestContext})=>({
  event:'shine-foundation/access-audit-event-v1',
  schemaVersion:'1.0.0',
  eventId:envelope.traceId,
  requestId:envelope.permission.requestId,
  appId:envelope.permission.appId,
  shineId:shineId??null,
  scope:envelope.permission.scope,
  purpose:envelope.permission.purpose,
  ...(envelope.permission.resourceId?{resourceId:envelope.permission.resourceId}:{}),
  ...(envelope.permission.resourceCategory?{resourceCategory:envelope.permission.resourceCategory}:{}),
  decision:decision.decision,
  reasonCode:decision.reasonCode,
  ...(decision.grantId?{grantId:decision.grantId}:{}),
  occurredAt,
  ...(defenceEvidenceRef?{defenceEvidenceRef}:{}),
  ...(requestContext&&Object.keys(requestContext).length?{requestContext}:{})
});

/** @param {{adapters:any, clock?:()=>string}} [options] */
export function createFoundationGateway({adapters,clock=()=>new Date().toISOString()}={}){
  for(const name of [
    'verifyAppCaller','verifyIdentity','getAppManifest','getVaultResource',
    'getEffectiveGrants','evaluateDependencyAdmission','evaluateDefence','writeAuditEvent'
  ]) requireFunction(adapters,name);

  return async function handleFoundationRequest({envelope,authContext}={}){
    if(!isEnvelopeValid(envelope)) return response(envelope,'invalid','invalid-gateway-request');

    const permission=envelope.permission;
    const v=requestVersion(envelope);
    const now=clock();

    const persistAndRespond=async(
      decision,
      defenceEvidenceRef,
      shineId=permission.shineId??null,
      requestContext={},
      externalStatus=null
    )=>{
      try{
        await adapters.writeAuditEvent(toAuditEvent({
          envelope,decision,defenceEvidenceRef,occurredAt:now,shineId,requestContext
        }));
      }catch{
        return response(envelope,'unavailable','audit-write-failed');
      }
      if(externalStatus==='unavailable'){
        return response(envelope,'unavailable',decision.reasonCode);
      }
      return response(
        envelope,
        decision.decision==='allow'?'allowed':'denied',
        decision.reasonCode,
        {decision:decision.decision,reasonCode:decision.reasonCode}
      );
    };

    let verifiedApp;
    try{
      verifiedApp=await adapters.verifyAppCaller({authContext,claimedAppId:permission.appId});
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }

    if(!verifiedApp?.appId){
      return persistAndRespond({decision:'deny',reasonCode:'app-caller-unverified'},undefined,null);
    }
    if(verifiedApp.appId!==permission.appId){
      return persistAndRespond({decision:'deny',reasonCode:'app-caller-mismatch'},undefined,null);
    }

    let verified;
    try{
      verified=await adapters.verifyIdentity({authContext,claimedAppId:permission.appId});
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }

    if(!verified?.shineId){
      return persistAndRespond({decision:'deny',reasonCode:'identity-unverified'},undefined,null);
    }
    if(v===1 && permission.shineId!==verified.shineId){
      return persistAndRespond({decision:'deny',reasonCode:'identity-mismatch'},undefined,verified.shineId);
    }
    if(v===2 && permission.shineId && permission.shineId!==verified.shineId){
      return persistAndRespond({decision:'deny',reasonCode:'identity-mismatch'},undefined,verified.shineId);
    }

    const effectiveRequest={...permission,shineId:verified.shineId};

    let manifest;
    try{
      manifest=await adapters.getAppManifest({appId:effectiveRequest.appId});
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }

    if(!manifest || manifest.appId!==effectiveRequest.appId || !appManifestDeclaresPermission(manifest,effectiveRequest)){
      const decision=evaluateAccess({
        request:effectiveRequest,
        verifiedShineId:verified.shineId,
        appManifest:manifest
      });
      return persistAndRespond(decision,undefined,verified.shineId);
    }

    let dependencyAdmission;
    try{
      dependencyAdmission=await adapters.evaluateDependencyAdmission({
        serviceId:'foundation.gateway',
        environment:'production',
        operation:envelope.operation,
        asOf:now
      });
    }catch{
      return response(envelope,'unavailable','dependency-admission-unavailable');
    }

    const admissionContext={
      dependencyAdmission:{
        admissionState:dependencyAdmission?.admissionState??'unavailable',
        reasonCode:dependencyAdmission?.reasonCode??'dependency-admission-invalid',
        serviceId:dependencyAdmission?.serviceId??'foundation.gateway',
        environment:dependencyAdmission?.environment??'production',
        operation:dependencyAdmission?.operation??envelope.operation,
        impactScope:dependencyAdmission?.impactScope??null,
        ownState:dependencyAdmission?.ownState??null,
        effectiveState:dependencyAdmission?.effectiveState??null,
        safeMode:dependencyAdmission?.safeMode??null,
        bindingEvidenceRef:dependencyAdmission?.bindingEvidenceRef??null,
        dependencyEvidence:Array.isArray(dependencyAdmission?.dependencyEvidence)
          ?dependencyAdmission.dependencyEvidence:[]
      }
    };

    if(!dependencyAdmission?.admissionState){
      return persistAndRespond(
        {decision:'deny',reasonCode:'dependency-admission-invalid'},
        undefined,
        verified.shineId,
        admissionContext,
        'unavailable'
      );
    }

    if(dependencyAdmission.admissionState==='deny'){
      return persistAndRespond(
        {decision:'deny',reasonCode:dependencyAdmission.reasonCode??'dependency-guarded'},
        undefined,
        verified.shineId,
        admissionContext
      );
    }

    if(dependencyAdmission.admissionState==='unavailable'){
      return persistAndRespond(
        {decision:'deny',reasonCode:dependencyAdmission.reasonCode??'dependency-admission-unavailable'},
        undefined,
        verified.shineId,
        admissionContext,
        'unavailable'
      );
    }

    if(!['admit','admit-degraded'].includes(dependencyAdmission.admissionState)){
      return persistAndRespond(
        {decision:'deny',reasonCode:'dependency-admission-invalid'},
        undefined,
        verified.shineId,
        admissionContext,
        'unavailable'
      );
    }

    let resource,grants;
    try{
      [resource,grants]=await Promise.all([
        adapters.getVaultResource({
          resourceId:effectiveRequest.resourceId,
          resourceCategory:effectiveRequest.resourceCategory,
          ownerShineId:verified.shineId
        }),
        adapters.getEffectiveGrants({
          shineId:verified.shineId,
          appId:effectiveRequest.appId,
          scope:effectiveRequest.scope,
          purpose:effectiveRequest.purpose
        })
      ]);
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }

    let defence;
    try{
      defence=await adapters.evaluateDefence({
        envelope:{...envelope,permission:effectiveRequest},
        verifiedIdentity:verified,
        verifiedApp,
        appManifest:manifest,
        resource
      });
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }

    const decision=evaluateAccess({
      request:effectiveRequest,
      verifiedShineId:verified.shineId,
      appManifest:manifest,
      resource,
      grants:Array.isArray(grants)?grants:[],
      now,
      defenceDecision:defence?.decision??'not-evaluated'
    });

    return persistAndRespond(
      decision,
      defence?.evidenceRef,
      verified.shineId,
      admissionContext
    );
  };
}

export const DENY_REASONS = Object.freeze({
  MALFORMED_REQUEST: 'malformed-request',
  IDENTITY_UNVERIFIED: 'identity-unverified',
  IDENTITY_MISMATCH: 'identity-mismatch',
  APP_UNREGISTERED: 'app-unregistered',
  SCOPE_NOT_DECLARED: 'scope-not-declared',
  RESOURCE_NOT_FOUND: 'resource-not-found',
  RESOURCE_OWNER_MISMATCH: 'resource-owner-mismatch',
  NO_MATCHING_GRANT: 'no-matching-grant',
  GRANT_INACTIVE: 'grant-inactive',
  GRANT_NOT_YET_ACTIVE: 'grant-not-yet-active',
  GRANT_EXPIRED: 'grant-expired',
  GRANT_REVOKED: 'grant-revoked',
  SCOPE_MISMATCH: 'scope-mismatch',
  PURPOSE_MISMATCH: 'purpose-mismatch',
  RESOURCE_MISMATCH: 'resource-mismatch',
  DEFENCE_DENIED: 'defence-denied'
});

const deny=(request,reasonCode,extra={})=>({
  requestId:request?.requestId ?? null,
  decision:'deny',
  reasonCode,
  ...extra
});

const resourceMatches=(selector,request,resource)=>{
  if(!selector || !resource) return false;
  if(selector.resourceId){
    return selector.resourceId===request.resourceId && resource.resourceId===selector.resourceId;
  }
  if(selector.resourceCategory){
    return selector.resourceCategory===request.resourceCategory &&
      resource.category===selector.resourceCategory;
  }
  return false;
};

const grantTimeState=(grant,nowMs)=>{
  if(grant.status==='revoked' || grant.revokedAt) return DENY_REASONS.GRANT_REVOKED;
  if(grant.status!=='active') return DENY_REASONS.GRANT_INACTIVE;
  if(grant.notBefore && Date.parse(grant.notBefore)>nowMs) return DENY_REASONS.GRANT_NOT_YET_ACTIVE;
  if(grant.expiresAt && Date.parse(grant.expiresAt)<=nowMs) return DENY_REASONS.GRANT_EXPIRED;
  return null;
};

export const appManifestDeclaresPermission=(manifest,request)=>{
  if(!manifest || manifest.appId!==request.appId) return false;
  const scopes=manifest.foundation?.requestedScopes;
  if(!Array.isArray(scopes)) return false;
  return scopes.some(entry=>{
    if(entry.scope!==request.scope || entry.purpose!==request.purpose) return false;
    if(entry.resourceCategory && entry.resourceCategory!==request.resourceCategory) return false;
    return true;
  });
};

export function evaluateAccess({
  request,
  verifiedShineId,
  appManifest,
  resource,
  grants=[],
  now=new Date().toISOString(),
  defenceDecision='not-evaluated'
}={}){
  if(!request || !request.requestId || !request.appId || !request.shineId || !request.scope || !request.purpose){
    return deny(request,DENY_REASONS.MALFORMED_REQUEST);
  }

  if(!verifiedShineId) return deny(request,DENY_REASONS.IDENTITY_UNVERIFIED);
  if(verifiedShineId!==request.shineId) return deny(request,DENY_REASONS.IDENTITY_MISMATCH);
  if(!appManifest || appManifest.appId!==request.appId) return deny(request,DENY_REASONS.APP_UNREGISTERED);
  if(!appManifestDeclaresPermission(appManifest,request)) return deny(request,DENY_REASONS.SCOPE_NOT_DECLARED);
  if(!resource) return deny(request,DENY_REASONS.RESOURCE_NOT_FOUND);
  if(resource.ownerShineId!==request.shineId) return deny(request,DENY_REASONS.RESOURCE_OWNER_MISMATCH);

  const sameIdentityAndApp=grants.filter(g=>g.ownerShineId===request.shineId && g.appId===request.appId);
  if(!sameIdentityAndApp.length) return deny(request,DENY_REASONS.NO_MATCHING_GRANT);

  const sameScope=sameIdentityAndApp.filter(g=>g.scope===request.scope);
  if(!sameScope.length) return deny(request,DENY_REASONS.SCOPE_MISMATCH);

  const samePurpose=sameScope.filter(g=>g.purpose===request.purpose);
  if(!samePurpose.length) return deny(request,DENY_REASONS.PURPOSE_MISMATCH);

  const sameResource=samePurpose.filter(g=>resourceMatches(g.resourceSelector,request,resource));
  if(!sameResource.length) return deny(request,DENY_REASONS.RESOURCE_MISMATCH);

  const nowMs=Date.parse(now);
  if(Number.isNaN(nowMs)) return deny(request,DENY_REASONS.MALFORMED_REQUEST);

  let strongestTemporalReason=DENY_REASONS.GRANT_INACTIVE;
  const temporalRank={
    [DENY_REASONS.GRANT_REVOKED]:4,
    [DENY_REASONS.GRANT_EXPIRED]:3,
    [DENY_REASONS.GRANT_NOT_YET_ACTIVE]:2,
    [DENY_REASONS.GRANT_INACTIVE]:1
  };

  let matchedGrant=null;
  for(const grant of sameResource){
    const state=grantTimeState(grant,nowMs);
    if(!state){ matchedGrant=grant; break; }
    if(temporalRank[state]>temporalRank[strongestTemporalReason]) strongestTemporalReason=state;
  }

  if(!matchedGrant) return deny(request,strongestTemporalReason);

  if(defenceDecision==='deny'){
    return deny(request,DENY_REASONS.DEFENCE_DENIED,{grantId:matchedGrant.grantId});
  }

  return {
    requestId:request.requestId,
    decision:'allow',
    reasonCode:'grant-match',
    grantId:matchedGrant.grantId
  };
}

const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const APP=/^shine\.[a-z0-9][a-z0-9-]*$/;
const PROVIDER=/^[a-z0-9][a-z0-9._:-]*$/;

const response=(envelope,status,reasonCode)=>({
  identityClaimResponse:'shine-foundation/identity-claim-response-v1',
  schemaVersion:'1.0.0',
  requestId:envelope?.requestId??null,
  status,
  reasonCode
});

const valid=envelope=>{
  if(!envelope||envelope.identityClaim!=='shine-foundation/identity-claim-v1') return false;
  if(envelope.schemaVersion!=='1.0.0') return false;
  if(!UUID.test(envelope.requestId??'')) return false;
  if(!APP.test(envelope.appId??'')) return false;
  if(!PROVIDER.test(envelope.sourceProviderId??'')||!PROVIDER.test(envelope.targetProviderId??'')) return false;
  if(!Number.isFinite(Date.parse(envelope.requestedAt??''))) return false;
  if(envelope.sourceProviderId===envelope.targetProviderId) return false;
  return true;
};

const requireFunction=(adapters,name)=>{
  if(typeof adapters?.[name]!=='function') throw new TypeError('missing identity claim adapter: '+name);
};

/** @param {{adapters:any, clock?:()=>string, idFactory?:()=>string}} [options] */
export function createIdentityClaimService({
  adapters,
  clock=()=>new Date().toISOString(),
  idFactory=()=>crypto.randomUUID()
}={}){
  for(const name of [
    'verifyAppCaller','verifyClaimSource','verifyClaimTarget',
    'getAppManifest','evaluateDefence','completeIdentityClaim'
  ]) requireFunction(adapters,name);

  return async function handleIdentityClaim({envelope,authContext}={}){
    if(!valid(envelope)) return response(envelope,'invalid','invalid-identity-claim-request');

    const requestedAt=Date.parse(envelope.requestedAt);
    const now=Date.parse(clock());
    if(!Number.isFinite(requestedAt)||!Number.isFinite(now)||
       requestedAt<now-10*60*1000||requestedAt>now+5*60*1000){
      return response(envelope,'invalid','stale-identity-claim-request');
    }

    let verifiedApp;
    try{
      verifiedApp=await adapters.verifyAppCaller({
        authContext,
        claimedAppId:envelope.appId
      });
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }

    if(!verifiedApp?.appId) return response(envelope,'denied','app-caller-unverified');
    if(verifiedApp.appId!==envelope.appId) return response(envelope,'denied','app-caller-mismatch');

    let source;
    try{
      source=await adapters.verifyClaimSource({
        appId:envelope.appId,
        providerId:envelope.sourceProviderId,
        userToken:authContext?.sourceUserToken
      });
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }
    if(!source?.authSubject||source.providerId!==envelope.sourceProviderId){
      return response(envelope,'denied','source-identity-unverified');
    }

    let target;
    try{
      target=await adapters.verifyClaimTarget({
        appId:envelope.appId,
        providerId:envelope.targetProviderId,
        jwt:authContext?.targetJwt
      });
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }
    if(!target?.shineId||!target?.authSubject||target.providerId!==envelope.targetProviderId){
      return response(envelope,'denied','target-identity-unverified');
    }

    let manifest;
    try{
      manifest=await adapters.getAppManifest({appId:envelope.appId});
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }
    if(!manifest||manifest.appId!==envelope.appId){
      return response(envelope,'denied','app-unregistered');
    }

    let defence;
    try{
      defence=await adapters.evaluateDefence({
        envelope:{
          operation:'identity.claim',
          identityClaim:envelope,
          context:{sourceProviderId:source.providerId,targetProviderId:target.providerId}
        },
        verifiedIdentity:{shineId:target.shineId},
        verifiedApp,
        appManifest:manifest,
        resource:null
      });
    }catch{
      return response(envelope,'unavailable','foundation-dependency-unavailable');
    }
    if(defence?.decision==='deny'){
      return response(envelope,'denied','defence-denied');
    }

    let result;
    try{
      result=await adapters.completeIdentityClaim({
        claimId:idFactory(),
        requestId:envelope.requestId,
        appId:envelope.appId,
        sourceProviderId:source.providerId,
        sourceSubject:source.authSubject,
        targetProviderId:target.providerId,
        targetSubject:target.authSubject,
        targetShineId:target.shineId,
        occurredAt:clock()
      });
    }catch{
      return response(envelope,'unavailable','identity-claim-write-failed');
    }

    if(!result?.outcome||!result?.reason_code){
      return response(envelope,'unavailable','identity-claim-write-failed');
    }

    if(result.outcome==='linked') return response(envelope,'linked',result.reason_code);
    if(result.outcome==='already-linked') return response(envelope,'already-linked',result.reason_code);
    return response(envelope,'denied',result.reason_code);
  };
}

