    const isRevocationAck=revocationAckPath(url.pathname);
    const isEvaluate=evaluatePath(url.pathname);
    if(!isConciergeRetryClaim&&!isConciergeRetryFinish&&!isConciergeSupersede&&!isUserConciergeCancel&&!isUserGrantRevoke&&!isUserLinkRevoke&&!isIntegrationDeviceLinkRequest&&!isIntegrationDeviceLinkApprove&&!isIntegrationDeviceLinkExchange&&!isIntegrationDelegationRefresh&&!isConciergePlan&&!isConciergeExecute&&!isIntegrationLinkConsent&&!isIntegrationLinkRevoke&&!isIntegrationGrantConsent&&!isIntegrationGrantRevoke&&!isClaim&&!isGrantConsent&&!isGrantRevocation&&!isRevocationAck&&!isEvaluate) return respond(404,{error:'not-found'});
    if(request.method!=='POST') return respond(405,{error:'method-not-allowed'});

    const contentType=request.headers.get('content-type')??'';
    if(!contentType.toLowerCase().startsWith('application/json')){
      return respond(415,{error:'unsupported-media-type'});
    }

    const declared=Number(request.headers.get('content-length'));
    if(Number.isFinite(declared)&&declared>maxBodyBytes) return respond(413,{error:'request-too-large'});

    let raw;
    try{ raw=await request.text(); }catch{ return respond(400,{error:'invalid-body'}); }
    if(new TextEncoder().encode(raw).byteLength>maxBodyBytes) return respond(413,{error:'request-too-large'});

    let envelope;
    try{ envelope=JSON.parse(raw); }catch{ return respond(400,{error:'invalid-json'}); }

    if(isConciergeRetryClaim||isConciergeRetryFinish){
      if(!conciergeRetry||typeof authenticateIntegrationClient!=='function') return respond(404,{error:'not-found'});
      let authContext;
      try{authContext=await authenticateIntegrationClient(request)}catch{return respond(401,{error:'unauthenticated'})}
      if(isConciergeRetryClaim){
        const clientId=String(envelope?.clientId??'');
        const result=await conciergeRetry.claim({clientId,authContext});
        const status={ok:200,denied:403,unavailable:503}[result.status]??400;
        return respond(status,result);
      }
      const result=await conciergeRetry.finish({envelope,authContext});
      const status={ok:200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isConciergeSupersede){
      if(typeof conciergeSupersede!=='function'||typeof authenticateIntegrationUserAndClient!=='function'){
        return respond(404,{error:'not-found'});
      }
      let authContext;
      try{authContext=await authenticateIntegrationUserAndClient(request)}catch{return respond(401,{error:'unauthenticated'})}
      const result=await conciergeSupersede({envelope,authContext});
      const status={superseded:200,'already-superseded':200,retired:200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isUserConciergeCancel){
      if(typeof userConciergeCancellation!=='function'||typeof authenticateIntegrationUser!=='function'){
        return respond(404,{error:'not-found'});
      }
      let authContext;
      try{authContext=await authenticateIntegrationUser(request)}catch{return respond(401,{error:'unauthenticated'})}
      const result=await userConciergeCancellation({envelope,authContext});
      const status={cancelled:200,'already-cancelled':200,retired:200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isUserGrantRevoke||isUserLinkRevoke){
      if(typeof authenticateIntegrationUser!=='function') return respond(404,{error:'not-found'});
      let authContext;
      try{authContext=await authenticateIntegrationUser(request)}catch{return respond(401,{error:'unauthenticated'})}
      const service=isUserGrantRevoke?userIntegrationGrantRevocation:userIntegrationLinkRevocation;
      if(typeof service!=='function') return respond(404,{error:'not-found'});
      const result=await service({envelope,authContext});
      const status={revoked:200,'already-revoked':200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isIntegrationDeviceLinkRequest){
      if(typeof integrationLinkRequest!=='function'||typeof authenticateIntegrationClient!=='function'){
        return respond(404,{error:'not-found'});
      }
      let authContext;
      try{authContext=await authenticateIntegrationClient(request)}catch{return respond(401,{error:'unauthenticated'})}
      const result=await integrationLinkRequest({envelope,authContext});
      const status={created:201,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isIntegrationDeviceLinkApprove){
      if(typeof integrationLinkApproval!=='function'||typeof authenticateIntegrationUser!=='function'){
        return respond(404,{error:'not-found'});
      }
      let authContext;
      try{authContext=await authenticateIntegrationUser(request)}catch{return respond(401,{error:'unauthenticated'})}
      const result=await integrationLinkApproval({envelope,authContext});
      const status={approved:200,'already-approved':200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isIntegrationDelegationRefresh){
      if(typeof integrationDelegationRefresh!=='function'||typeof authenticateIntegrationClient!=='function'){
        return respond(404,{error:'not-found'});
      }
      let authContext;
      try{authContext=await authenticateIntegrationClient(request)}catch{return respond(401,{error:'unauthenticated'})}
      const result=await integrationDelegationRefresh({envelope,authContext});
      const status={refreshed:200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isIntegrationDeviceLinkExchange){
      if(typeof integrationLinkExchange!=='function'||typeof authenticateIntegrationClient!=='function'){
        return respond(404,{error:'not-found'});
      }
      let authContext;
      try{authContext=await authenticateIntegrationClient(request)}catch{return respond(401,{error:'unauthenticated'})}
      const result=await integrationLinkExchange({envelope,authContext});
      const status={exchanged:200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isConciergePlan||isConciergeExecute){
      if(typeof authenticateIntegrationUserAndClient!=='function') return respond(404,{error:'not-found'});
      let authContext;
      try{authContext=await authenticateIntegrationUserAndClient(request)}catch{return respond(401,{error:'unauthenticated'})}
      const service=isConciergePlan?conciergePlan:conciergeExecute;
      if(typeof service!=='function') return respond(404,{error:'not-found'});
      const result=await service({envelope,authContext});
      const status={planned:200,ready:202,completed:200,partial:200,failed:502,blocked:409,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isIntegrationLinkConsent||isIntegrationLinkRevoke||isIntegrationGrantConsent||isIntegrationGrantRevoke){
      if(typeof authenticateIntegrationUserAndClient!=='function') return respond(404,{error:'not-found'});
      let authContext;
      try{authContext=await authenticateIntegrationUserAndClient(request)}catch{return respond(401,{error:'unauthenticated'})}

      const service=isIntegrationLinkConsent?integrationLinkConsent:
        isIntegrationLinkRevoke?integrationLinkRevocation:
        isIntegrationGrantConsent?integrationCapabilityConsent:
        integrationGrantRevocation;
      if(typeof service!=='function') return respond(404,{error:'not-found'});

      const result=await service({envelope,authContext});
      const status={
        linked:200,'already-linked':200,granted:200,'already-granted':200,
        revoked:200,'already-revoked':200,denied:403,invalid:400,unavailable:503
      }[result.status]??500;
      return respond(status,result);
    }

    if(isRevocationAck){
      if(typeof revocationAck!=='function'||typeof authenticateApp!=='function'){
        return respond(404,{error:'not-found'});
      }
      let authContext;
      try{ authContext=await authenticateApp(request); }catch{ return respond(401,{error:'unauthenticated'}); }
      const result=await revocationAck({envelope,authContext});
      const status={acknowledged:200,'already-acknowledged':200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isClaim){
      if(typeof identityClaim!=='function'||typeof authenticateIdentityClaim!=='function'){
        return respond(404,{error:'not-found'});
      }

      let authContext;
      try{ authContext=await authenticateIdentityClaim(request); }catch{ return respond(401,{error:'unauthenticated'}); }

      const result=await identityClaim({envelope,authContext});
      const status={
        linked:200,
        'already-linked':200,
        denied:403,
        invalid:400,
        unavailable:503
      }[result.status]??500;
      return respond(status,result);
    }

    let authContext;
    try{ authContext=await authenticate(request); }catch{ return respond(401,{error:'unauthenticated'}); }

    if(isGrantConsent){
      if(typeof grantConsent!=='function') return respond(404,{error:'not-found'});
      const result=await grantConsent({envelope,authContext});
      const status={granted:200,'already-granted':200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    if(isGrantRevocation){
      if(typeof grantRevocation!=='function') return respond(404,{error:'not-found'});
      const result=await grantRevocation({envelope,authContext});
      const status={revoked:200,'already-revoked':200,denied:403,invalid:400,unavailable:503}[result.status]??500;
      return respond(status,result);
    }

    const result=await gateway({envelope,authContext});
    const status={allowed:200,denied:403,invalid:400,unavailable:503}[result.status]??500;
    return respond(status,result);
  };
}

const SHA=/^[a-f0-9]{40}$/;
const APP=/^[a-z0-9][a-z0-9-]{0,63}$/;
const DISPLAY={
  reviewed_release:'Protected by Shine Defence',
  revoked_release:'Defence certification withdrawn',
  unreviewed_revision:'Defence review pending for this revision',
  profile_drift:'Defence profile changed since review',
  uncertified:'No reviewed Shine Defence release'
};

const publicResult=(state,app,extra={})=>({
  defenceStatus:'shine-defence/public-release-status-v1',
  schemaVersion:'1.0.0',
  appId:app?.id??extra.appId,
  state,
  badgeCurrent:state==='reviewed_release',
  display:DISPLAY[state],
  ...(app?{
    reviewedCommitSha:app.reviewCommitSha,
    reviewedProfileBlobSha:app.profileBlobSha,
    reviewedProfileVersion:app.profileVersion,
    policies:[...app.policies]
  }:{}),
  ...extra
});

export function createPublicDefenceStatusService({ledger,revocations}={}){
  if(ledger?.ledger!=='shine-defence/ecosystem-profile-ledger-v1'||!Array.isArray(ledger?.apps)){
    throw new TypeError('valid Defence ecosystem ledger is required');
  }
  if(revocations?.ledger!=='shine-defence/revocations-v1'||!Array.isArray(revocations?.revocations)){
    throw new TypeError('valid Defence revocation ledger is required');
  }
  const apps=new Map(ledger.apps.map(app=>[app.id,app]));

  return function evaluate({appId,releaseSha,profileBlobSha}={}){
    if(!APP.test(appId||'')||!SHA.test(releaseSha||'')||!SHA.test(profileBlobSha||'')){
      throw new TypeError('invalid Defence status query');
    }
    const app=apps.get(appId);
    if(!app)return publicResult('uncertified',null,{appId});

    const revoked=revocations.revocations.find(item=>
      item.appId===appId&&
      item.reviewCommitSha===releaseSha&&
      item.profileBlobSha===profileBlobSha
    );
    if(revoked){
      return publicResult('revoked_release',app,{
        revocation:{
          revocationId:revoked.revocationId,
          revokedAt:revoked.revokedAt,
          reasonCode:revoked.reasonCode,
          publicReason:revoked.publicReason,
          ...(revoked.replacementReviewCommitSha?{replacementReviewCommitSha:revoked.replacementReviewCommitSha}:{})
        }
      });
    }
    if(releaseSha!==app.reviewCommitSha)return publicResult('unreviewed_revision',app);
    if(profileBlobSha!==app.profileBlobSha)return publicResult('profile_drift',app);
    return publicResult('reviewed_release',app);
  };
}

const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const TOKEN=/^[a-z0-9][a-z0-9._:-]*$/;
const reply=(e,status,reasonCode,extra={})=>({
  integrationContextPublishResponse:'shine-foundation/integration-context-publish-response-v1',
  schemaVersion:'1.0.0',requestId:e?.requestId??null,status,reasonCode,...extra
});
const fresh=(v,clock)=>{
  const t=Date.parse(v??''),n=Date.parse(clock());
  return Number.isFinite(t)&&Number.isFinite(n)&&t>=n-600000&&t<=n+300000;
};

export function createIntegrationContextPublishService({adapters,clock=()=>new Date().toISOString(),idFactory=()=>crypto.randomUUID()}={}){
  for(const n of ['verifyAppCaller','resolveIntegrationSubjectOwner','getIntegrationContextPublishEvent','publishIntegrationContextSnapshot']){
    if(typeof adapters?.[n]!=='function')throw new TypeError('missing context publish adapter: '+n);
  }
  return async function handle({envelope,authContext}={}){
    if(!envelope||envelope.integrationContextPublish!=='shine-foundation/integration-context-publish-v1'||
      envelope.schemaVersion!=='1.0.0'||!UUID.test(envelope.requestId??'')||
      !TOKEN.test(envelope.appId??'')||
      typeof envelope.subjectId!=='string'||envelope.subjectId.length<1||envelope.subjectId.length>256||
      !TOKEN.test(envelope.contextKind??'')||
      typeof envelope.resourceId!=='string'||envelope.resourceId.length<1||envelope.resourceId.length>256||
      !Number.isSafeInteger(envelope.sourceRevision)||envelope.sourceRevision<1||
      !envelope.payload||typeof envelope.payload!=='object'||Array.isArray(envelope.payload)||
      !fresh(envelope.requestedAt,clock)){
      return reply(envelope,'invalid','invalid-integration-context-publish');
    }
    if(new TextEncoder().encode(JSON.stringify(envelope.payload)).byteLength>1048576){
      return reply(envelope,'invalid','integration-context-payload-too-large');
    }
    let caller;
    try{caller=await adapters.verifyAppCaller({authContext,claimedAppId:envelope.appId})}
    catch{return reply(envelope,'unavailable','app-authentication-unavailable')}
    if(!caller?.appId)return reply(envelope,'denied','app-unverified');
    if(caller.appId!==envelope.appId)return reply(envelope,'denied','app-mismatch');

    let owner;
    try{owner=await adapters.resolveIntegrationSubjectOwner({appId:envelope.appId,subjectId:envelope.subjectId})}
    catch{return reply(envelope,'unavailable','subject-binding-lookup-unavailable')}
    if(owner?.ambiguous)return reply(envelope,'denied','subject-binding-ambiguous');
    if(!owner?.ownerShineId)return reply(envelope,'denied','subject-binding-not-active');

    let prior;
    try{prior=await adapters.getIntegrationContextPublishEvent({requestId:envelope.requestId})}
    catch{return reply(envelope,'unavailable','context-publish-replay-check-unavailable')}
    if(prior){
      if(prior.appId!==envelope.appId||prior.subjectId!==envelope.subjectId||
        prior.contextKind!==envelope.contextKind||prior.resourceId!==envelope.resourceId){
        return reply(envelope,'invalid','integration-context-publish-replay-conflict');
      }
      return reply(envelope,'already-published','integration-context-already-published',{snapshotId:prior.snapshotId??null});
    }

    let result;
    try{result=await adapters.publishIntegrationContextSnapshot({
      eventId:idFactory(),requestId:envelope.requestId,ownerShineId:owner.ownerShineId,
      appId:envelope.appId,subjectId:envelope.subjectId,contextKind:envelope.contextKind,
      resourceId:envelope.resourceId,sourceRevision:envelope.sourceRevision,payload:envelope.payload,
      sourceUpdatedAt:envelope.sourceUpdatedAt??null,occurredAt:clock()
    })}catch{return reply(envelope,'unavailable','context-snapshot-publish-failed')}

    if(result?.outcome==='published')return reply(envelope,'published',result.reasonCode??'context-snapshot-published',{
      snapshotId:result.snapshotId??null,sourceRevision:result.sourceRevision??envelope.sourceRevision,
      contentHash:result.contentHash??null
    });
    return reply(envelope,'denied',result?.reasonCode??'context-snapshot-publish-denied');
  };
}

import {validateAtlasFeedEvent} from '../runtime/validate-feed-event-v1.mjs';

const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const TOKEN=/^[a-z0-9][a-z0-9._:-]*$/;
const PRIVATE_CLASSES=new Set(['personal','sensitive']);
const PERMISSION_KEYS=new Set(['ownerShineId','requiredScope','purpose','resourceId','resourceCategory']);

const response=(envelope,status,reasonCode,extra={})=>({
  atlasFeedPublisherAdmissionResponse:'shine-universe/atlas-feed-publisher-admission-response-v1',
  schemaVersion:'1.0.0',
  requestId:envelope?.requestId??null,
  status,
  reasonCode,
  ...extra
});

const isObject=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);

const fresh=(value,clock)=>{
  const requested=Date.parse(value??'');
  const now=Date.parse(clock());
  return Number.isFinite(requested)&&Number.isFinite(now)&&requested>=now-600000&&requested<=now+300000;
};

const hasOnlyKeys=(value,allowed)=>{
  if(!isObject(value)) return false;
  return Object.keys(value).every(key=>allowed.has(key));
};

const grantMatchesResource=(grant,permission)=>{
  if(permission.resourceId!==undefined){
    if(!UUID.test(permission.resourceId)||grant.resourceId!==permission.resourceId) return false;
  }
  if(permission.resourceCategory!==undefined){
    if(typeof permission.resourceCategory!=='string'||!TOKEN.test(permission.resourceCategory)||
      grant.resourceCategory!==permission.resourceCategory) return false;
  }
  return true;
};

export function createAtlasFeedPublisherAdmissionService({
  adapters,
  clock=()=>new Date().toISOString()
}={}){
  for(const name of [
    'verifyAppCaller',
    'verifyIdentity',
    'getAtlasFeedPublisherCapability',
    'getAtlasFeedGrantContext'
  ]){
    if(typeof adapters?.[name]!=='function'){
      throw new TypeError('missing Atlas Feed publisher admission adapter: '+name);
    }
  }

  return async function admit({envelope,authContext}={}){
    if(!isObject(envelope)||
      envelope.atlasFeedPublishAdmissionRequest!=='shine-universe/atlas-feed-publisher-admission-v1'||
      envelope.schemaVersion!=='1.0.0'||
      !UUID.test(envelope.requestId??'')||
      !fresh(envelope.requestedAt,clock)||
      !isObject(envelope.event)||
      !Object.keys(envelope).every(key=>[
        'atlasFeedPublishAdmissionRequest','schemaVersion','requestId','requestedAt','event','permissionContext'
      ].includes(key))){
      return response(envelope,'invalid','invalid-publisher-admission-request');
    }

    const eventValidation=validateAtlasFeedEvent(envelope.event);
    if(!eventValidation.ok){
      return response(envelope,'invalid','invalid-atlas-feed-event',{
        validationErrors:eventValidation.errors.slice(0,12)
      });
    }

    const permission=envelope.permissionContext??{};
    if(!hasOnlyKeys(permission,PERMISSION_KEYS)){
      return response(envelope,'invalid','invalid-permission-context');
    }

    const appId=envelope.event.source.appId;
    let caller;
    try{
      caller=await adapters.verifyAppCaller({authContext,claimedAppId:appId});
    }catch{
      return response(envelope,'unavailable','app-authentication-unavailable');
    }
    if(!caller?.appId) return response(envelope,'denied','publishing-app-unverified');
    if(caller.appId!==appId) return response(envelope,'denied','publishing-app-mismatch');

    let capability;
    try{
      capability=await adapters.getAtlasFeedPublisherCapability({
        appId,
        capabilityId:envelope.event.source.capabilityId
      });
    }catch{
      return response(envelope,'unavailable','publisher-capability-lookup-unavailable');
    }
    if(!capability) return response(envelope,'denied','publisher-capability-not-registered');
    if(capability.appId!==appId) return response(envelope,'denied','publisher-capability-app-mismatch');
    if(capability.invocationState!=='live') return response(envelope,'denied','publisher-capability-not-live');

    const {mode,dataClass,grantId}=envelope.event.audience;
    const privateData=PRIVATE_CLASSES.has(dataClass);

    if(privateData&&mode==='internal'){
      return response(envelope,'denied','private-internal-audience-not-supported');
    }

    let owner=null;
    if(privateData){
      if(typeof permission.ownerShineId!=='string'||!UUID.test(permission.ownerShineId)){
        return response(envelope,'invalid','private-publication-owner-required');
      }
      try{
        owner=await adapters.verifyIdentity({authContext,claimedAppId:appId});
      }catch{
        return response(envelope,'unavailable','owner-authentication-unavailable');
      }
      if(!owner?.shineId) return response(envelope,'denied','owner-session-unverified');
      if(owner.shineId!==permission.ownerShineId){
        return response(envelope,'denied','owner-identity-mismatch');
      }
    }else if(permission.ownerShineId!==undefined&&
      (typeof permission.ownerShineId!=='string'||!UUID.test(permission.ownerShineId))){
      return response(envelope,'invalid','invalid-owner-shine-id');
    }

    let grant=null;
    if(mode==='grant'){
      if(typeof grantId!=='string'||!UUID.test(grantId)){
        return response(envelope,'invalid','grant-audience-requires-foundation-grant-id');
      }
      if(typeof permission.requiredScope!=='string'||!TOKEN.test(permission.requiredScope)||
        typeof permission.purpose!=='string'||!TOKEN.test(permission.purpose)){
        return response(envelope,'invalid','grant-audience-scope-purpose-required');
      }
      if(permission.resourceId===undefined&&permission.resourceCategory===undefined){
        return response(envelope,'invalid','grant-audience-resource-context-required');
      }
      try{
        grant=await adapters.getAtlasFeedGrantContext({grantId});
      }catch{
        return response(envelope,'unavailable','grant-context-lookup-unavailable');
      }
      if(!grant||grant.effectiveStatus!=='active'){
        return response(envelope,'denied','grant-not-active');
      }
      if(grant.scope!==permission.requiredScope||grant.purpose!==permission.purpose){
        return response(envelope,'denied','grant-scope-purpose-mismatch');
      }
      if(!grantMatchesResource(grant,permission)){
        return response(envelope,'denied','grant-resource-mismatch');
      }
      if(privateData&&grant.ownerShineId!==permission.ownerShineId){
        return response(envelope,'denied','grant-owner-mismatch');
      }
    }else if(
      permission.requiredScope!==undefined||
      permission.purpose!==undefined||
      permission.resourceId!==undefined||
      permission.resourceCategory!==undefined
    ){
      return response(envelope,'invalid','grant-context-without-grant-audience');
    }

    return response(envelope,'admitted','publisher-admission-clear',{
      admission:{
        eventId:envelope.event.eventId,
        appId,
        credentialId:caller.credentialId??null,
        capabilityId:capability.capabilityId,
        capabilityVersion:capability.capabilityVersion??null,
        capabilityState:capability.invocationState,
        audienceMode:mode,
        dataClass,
        ownerShineId:permission.ownerShineId??grant?.ownerShineId??null,
        grantId:grant?.grantId??null
      }
    });
  };
}

const CONTRACT_ID = 'shine-universe/atlas-feed-event';
const SCHEMA_VERSION = '1.0.0';
const TOP_LEVEL = new Set([
  'atlasFeedEvent',
  'schemaVersion',
  'eventId',
  'topic',
  'source',
  'subject',
  'timing',
  'audience',
  'provenance',
  'payloadContract',
  'payload'
]);
const FORBIDDEN_PAYLOAD_KEYS = new Set([
  'password',
  'secret',
  'token',
  'api_key',
  'apikey',
  'authorization',
  'cookie',
  'set-cookie'
]);
const AUDIENCE_MODES = new Set(['owner', 'grant', 'internal']);
const DATA_CLASSES = new Set(['general', 'personal', 'sensitive']);
const PROVENANCE_MODES = new Set(['first_party', 'external', 'derived', 'mixed']);
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const NAMESPACE_RE = /^[a-z0-9]+(?:[._-][a-z0-9]+){1,7}$/;
const SEMVER_RE = /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/;

function object(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function exactKeys(value, allowed, prefix, errors) {
  if (!object(value)) {
    errors.push(`${prefix} must be an object`);
    return false;
  }
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) errors.push(`${prefix}.${key} is not allowed`);
  }
  return true;
}

function required(value, fields, prefix, errors) {
  for (const field of fields) {
    if (!(field in value)) errors.push(`${prefix}.${field} is required`);
  }
}

function boundedString(value, prefix, max, errors) {
  if (typeof value !== 'string' || value.length === 0) {
    errors.push(`${prefix} must be a non-empty string`);
    return false;
  }
  if (value.length > max) errors.push(`${prefix} exceeds ${max} characters`);
  return true;
}

function parseDate(value, prefix, errors) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}T/.test(value)) {
    errors.push(`${prefix} must be an ISO date-time string`);
    return null;
  }
  const timestamp = Date.parse(value);
  if (!Number.isFinite(timestamp)) {
    errors.push(`${prefix} must be a valid date-time`);
    return null;
  }
  return timestamp;
}

function inspectPayload(value, depth, errors, path) {
  if (depth > 8) {
    errors.push('payload exceeds maximum depth of 8');
    return;
  }
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i += 1) {
      inspectPayload(value[i], depth + 1, errors, `${path}[${i}]`);
    }
    return;
  }
  if (!object(value)) return;

  for (const [key, child] of Object.entries(value)) {
    const normalised = key.toLowerCase();
    if (FORBIDDEN_PAYLOAD_KEYS.has(normalised)) {
      errors.push(`${path}.${key} is a forbidden credential-bearing key`);
    }
    if (key === '__proto__' || key === 'prototype' || key === 'constructor') {
      errors.push(`${path}.${key} is forbidden`);
    }
    inspectPayload(child, depth + 1, errors, `${path}.${key}`);
  }
}

export function validateAtlasFeedEvent(event) {
  const errors = [];

  if (!exactKeys(event, TOP_LEVEL, 'event', errors)) {
    return {ok: false, errors};
  }

  required(event, [...TOP_LEVEL], 'event', errors);

  if (event.atlasFeedEvent !== CONTRACT_ID) errors.push(`event.atlasFeedEvent must equal ${CONTRACT_ID}`);
  if (event.schemaVersion !== SCHEMA_VERSION) errors.push(`event.schemaVersion must equal ${SCHEMA_VERSION}`);
  if (typeof event.eventId !== 'string' || !UUID_RE.test(event.eventId)) errors.push('event.eventId must be a UUID');
  if (typeof event.topic !== 'string' || !NAMESPACE_RE.test(event.topic)) errors.push('event.topic must be a lowercase namespaced string');

  if (exactKeys(event.source, new Set(['appId', 'capabilityId', 'releaseRef']), 'event.source', errors)) {
    required(event.source, ['appId', 'capabilityId', 'releaseRef'], 'event.source', errors);
    boundedString(event.source.appId, 'event.source.appId', 100, errors);
    boundedString(event.source.capabilityId, 'event.source.capabilityId', 160, errors);
    boundedString(event.source.releaseRef, 'event.source.releaseRef', 200, errors);
  }

  if (exactKeys(event.subject, new Set(['kind', 'key']), 'event.subject', errors)) {
    required(event.subject, ['kind', 'key'], 'event.subject', errors);
    boundedString(event.subject.kind, 'event.subject.kind', 64, errors);
    boundedString(event.subject.key, 'event.subject.key', 200, errors);
  }

  if (exactKeys(event.timing, new Set(['occurredAt', 'publishedAt', 'freshForSeconds', 'expiresAt']), 'event.timing', errors)) {
    required(event.timing, ['occurredAt', 'publishedAt', 'freshForSeconds'], 'event.timing', errors);
    const occurredAt = parseDate(event.timing.occurredAt, 'event.timing.occurredAt', errors);
    const publishedAt = parseDate(event.timing.publishedAt, 'event.timing.publishedAt', errors);
    if (occurredAt !== null && publishedAt !== null && publishedAt < occurredAt) {
      errors.push('event.timing.publishedAt must not precede occurredAt');
    }
    if (!Number.isInteger(event.timing.freshForSeconds) || event.timing.freshForSeconds < 0 || event.timing.freshForSeconds > 604800) {
      errors.push('event.timing.freshForSeconds must be an integer from 0 to 604800');
    }
    if ('expiresAt' in event.timing) {
      const expiresAt = parseDate(event.timing.expiresAt, 'event.timing.expiresAt', errors);
      if (expiresAt !== null && publishedAt !== null && expiresAt <= publishedAt) {
        errors.push('event.timing.expiresAt must be after publishedAt');
      }
    }
  }

  if (exactKeys(event.audience, new Set(['mode', 'grantId', 'dataClass']), 'event.audience', errors)) {
    required(event.audience, ['mode', 'dataClass'], 'event.audience', errors);
    if (!AUDIENCE_MODES.has(event.audience.mode)) errors.push('event.audience.mode is invalid');
    if (!DATA_CLASSES.has(event.audience.dataClass)) errors.push('event.audience.dataClass is invalid');
    if (event.audience.mode === 'grant') {
      boundedString(event.audience.grantId, 'event.audience.grantId', 160, errors);
    } else if ('grantId' in event.audience) {
      errors.push('event.audience.grantId is allowed only when mode=grant');
    }
  }

  if (exactKeys(event.provenance, new Set(['mode', 'sourceObservedAt', 'evidenceRefs']), 'event.provenance', errors)) {
    required(event.provenance, ['mode', 'sourceObservedAt', 'evidenceRefs'], 'event.provenance', errors);
    if (!PROVENANCE_MODES.has(event.provenance.mode)) errors.push('event.provenance.mode is invalid');
    parseDate(event.provenance.sourceObservedAt, 'event.provenance.sourceObservedAt', errors);
    if (!Array.isArray(event.provenance.evidenceRefs) || event.provenance.evidenceRefs.length > 12) {
      errors.push('event.provenance.evidenceRefs must be an array with at most 12 items');
    } else {
      for (let i = 0; i < event.provenance.evidenceRefs.length; i += 1) {
        boundedString(event.provenance.evidenceRefs[i], `event.provenance.evidenceRefs[${i}]`, 240, errors);
      }
      if (event.provenance.mode !== 'first_party' && event.provenance.evidenceRefs.length === 0) {
        errors.push('non-first-party provenance requires at least one evidenceRef');
      }
    }
  }

  if (exactKeys(event.payloadContract, new Set(['schemaRef', 'schemaVersion']), 'event.payloadContract', errors)) {
    required(event.payloadContract, ['schemaRef', 'schemaVersion'], 'event.payloadContract', errors);
    if (typeof event.payloadContract.schemaRef !== 'string' || !NAMESPACE_RE.test(event.payloadContract.schemaRef)) {
      errors.push('event.payloadContract.schemaRef must be a lowercase namespaced string');
    }
    if (typeof event.payloadContract.schemaVersion !== 'string' || !SEMVER_RE.test(event.payloadContract.schemaVersion)) {
      errors.push('event.payloadContract.schemaVersion must be semver');
    }
  }

  if (!object(event.payload)) {
    errors.push('event.payload must be an object');
  } else {
    let size = Infinity;
    try {
      size = Buffer.byteLength(JSON.stringify(event.payload), 'utf8');
    } catch {
      errors.push('event.payload must be JSON serializable');
    }
    if (size > 65536) errors.push('event.payload exceeds 65536 UTF-8 bytes');
    inspectPayload(event.payload, 1, errors, 'event.payload');
  }

  return {ok: errors.length === 0, errors};
}

export const ATLAS_FEED_EVENT_CONTRACT = Object.freeze({
  id: CONTRACT_ID,
  schemaVersion: SCHEMA_VERSION,
  maximumPayloadBytes: 65536,
  maximumPayloadDepth: 8,
  maximumFreshnessSeconds: 604800
});

const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const response=(envelope,status,reasonCode,extra={})=>({
  atlasFeedPublishResponse:'shine-universe/atlas-feed-publish-response-v1',
  schemaVersion:'1.0.0',
  requestId:envelope?.requestId??null,
  status,
  reasonCode,
  ...extra
});

const isObject=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);

export function canonicalJson(value){
  if(value===null||typeof value!=='object') return JSON.stringify(value);
  if(Array.isArray(value)) return '['+value.map(canonicalJson).join(',')+']';
  return '{'+Object.keys(value).sort().map(
    key=>JSON.stringify(key)+':'+canonicalJson(value[key])
  ).join(',')+'}';
}

export async function sha256CanonicalJson(value){
  const bytes=new TextEncoder().encode(canonicalJson(value));
  const digest=await crypto.subtle.digest('SHA-256',bytes);
  return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');
}

export function createAtlasFeedPublishService({
  publisherAdmission,
  adapters,
  clock=()=>new Date().toISOString(),
  idFactory=()=>crypto.randomUUID()
}={}){
  if(typeof publisherAdmission!=='function') throw new TypeError('publisherAdmission is required');
  if(typeof adapters?.persistAtlasFeedEvent!=='function'){
    throw new TypeError('missing Atlas Feed persistence adapter: persistAtlasFeedEvent');
  }

  return async function publish({envelope,authContext}={}){
    if(!isObject(envelope)||
      envelope.atlasFeedPublishRequest!=='shine-universe/atlas-feed-publish-v1'||
      envelope.schemaVersion!=='1.0.0'||
      !UUID.test(envelope.requestId??'')||
      !isObject(envelope.event)||
      !Object.keys(envelope).every(key=>[
        'atlasFeedPublishRequest','schemaVersion','requestId','requestedAt','event','permissionContext'
      ].includes(key))){
      return response(envelope,'invalid','invalid-atlas-feed-publish-request');
    }

    const admissionEnvelope={
      atlasFeedPublishAdmissionRequest:'shine-universe/atlas-feed-publisher-admission-v1',
      schemaVersion:'1.0.0',
      requestId:envelope.requestId,
      requestedAt:envelope.requestedAt,
      event:envelope.event,
      ...(envelope.permissionContext?{permissionContext:envelope.permissionContext}:{})
    };

    let admission;
    try{
      admission=await publisherAdmission({envelope:admissionEnvelope,authContext});
    }catch{
      return response(envelope,'unavailable','publisher-admission-unavailable');
    }

    if(admission?.status!=='admitted'){
      const status=['denied','invalid','unavailable'].includes(admission?.status)
        ?admission.status:'unavailable';
      return response(
        envelope,
        status,
        admission?.reasonCode??'publisher-admission-unavailable',
        admission?.validationErrors?{validationErrors:admission.validationErrors}:{}
      );
    }

    const admissionSnapshot=admission.admission;
    if(!isObject(admissionSnapshot)||
      admissionSnapshot.eventId!==envelope.event.eventId||
      admissionSnapshot.appId!==envelope.event.source.appId||
      admissionSnapshot.capabilityId!==envelope.event.source.capabilityId||
      admissionSnapshot.capabilityState!=='live'||
      !UUID.test(admissionSnapshot.credentialId??'')){
      return response(envelope,'unavailable','publisher-admission-invalid');
    }

    const persistedAt=clock();
    const receiptId=idFactory();
    if(!UUID.test(receiptId)||!Number.isFinite(Date.parse(persistedAt))){
      return response(envelope,'unavailable','persistence-runtime-invalid');
    }

    let eventSha256,payloadSha256,receiptSha256,payloadSizeBytes;
    const receiptBase={
      atlasFeedPersistenceReceipt:'shine-universe/atlas-feed-persistence-receipt-v1',
      schemaVersion:'1.0.0',
      receiptId,
      requestId:envelope.requestId,
      eventId:envelope.event.eventId,
      publisherAppId:admissionSnapshot.appId,
      capabilityId:admissionSnapshot.capabilityId,
      capabilityVersion:admissionSnapshot.capabilityVersion,
      persistedAt
    };

    try{
      const payloadCanonical=canonicalJson(envelope.event.payload);
      payloadSizeBytes=new TextEncoder().encode(payloadCanonical).byteLength;
      [eventSha256,payloadSha256]=await Promise.all([
        sha256CanonicalJson(envelope.event),
        sha256CanonicalJson(envelope.event.payload)
      ]);
      receiptBase.eventSha256=eventSha256;
      receiptBase.payloadSha256=payloadSha256;
      receiptSha256=await sha256CanonicalJson(receiptBase);
    }catch{
      return response(envelope,'unavailable','persistence-hash-failed');
    }

    let result;
    try{
      result=await adapters.persistAtlasFeedEvent({
        requestId:envelope.requestId,
        event:envelope.event,
        admission:admissionSnapshot,
        eventSha256,
        payloadSha256,
        payloadSizeBytes,
        receipt:receiptBase,
        receiptSha256,
        persistedAt
      });
    }catch{
      return response(envelope,'unavailable','event-store-unavailable');
    }

    if(result?.outcome==='conflict'){
      return response(envelope,'conflict',result.reasonCode??'atlas-feed-persistence-conflict',{
        eventId:envelope.event.eventId
      });
    }

    if(!['persisted','already-persisted'].includes(result?.outcome)||
      !isObject(result?.receipt)||
      typeof result?.receiptSha256!=='string'){
      return response(envelope,'unavailable','event-store-invalid-response');
    }

    return response(envelope,result.outcome,result.reasonCode??(
      result.outcome==='persisted'?'atlas-feed-event-persisted':'atlas-feed-event-already-persisted'
    ),{
      eventId:envelope.event.eventId,
      receipt:result.receipt,
      receiptSha256:result.receiptSha256
    });
  };
}

const first=rows=>Array.isArray(rows)&&rows.length?rows[0]:null;

export async function sha256Hex(value){
  if(typeof value!=='string'||!value) return null;
  const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));
  return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');
}

function decodeJwtPayload(jwt){
  try{
    const part=String(jwt||'').split('.')[1];
    if(!part) return null;
    const normalized=part.replace(/-/g,'+').replace(/_/g,'/');
    const padded=normalized+'='.repeat((4-normalized.length%4)%4);
    const binary=atob(padded);
    const bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));
    return JSON.parse(new TextDecoder().decode(bytes));
  }catch{
    return null;
  }
}

const normalizeJsonObject=value=>{
  if(value==null) return null;
  if(typeof value==='string'){
    try{
      const parsed=JSON.parse(value);
      return parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:null;
    }catch{
      return null;
    }
  }
  return typeof value==='object'&&!Array.isArray(value)?value:null;
};

const toIso=v=>v==null?undefined:(v instanceof Date?v.toISOString():String(v));

const mapResource=row=>row?{
  resourceId:String(row.resource_id),
  ownerShineId:String(row.owner_shine_id),
  category:String(row.category),
  sensitivity:String(row.sensitivity),
  ...(row.content_type?{contentType:String(row.content_type)}:{}),
  ...(row.storage_ref?{storageRef:String(row.storage_ref)}:{})
}:null;

const mapGrant=row=>({
  grantId:String(row.grant_id),
  ownerShineId:String(row.owner_shine_id),
  appId:String(row.app_id),
  scope:String(row.scope),
  purpose:String(row.purpose),
  resourceSelector:row.resource_id?{resourceId:String(row.resource_id)}:{resourceCategory:String(row.resource_category)},
  status:row.effective_status==='revoked'?'revoked':'active',
  issuedAt:toIso(row.issued_at),
  ...(row.not_before?{notBefore:toIso(row.not_before)}:{}),
  ...(row.expires_at?{expiresAt:toIso(row.expires_at)}:{}),
  ...(row.revoked_at?{revokedAt:toIso(row.revoked_at)}:{})
});

const sameAudit=(row,event)=>{
  const eq=(a,b)=>String(a??'')===String(b??'');
  return eq(row.app_id,event.appId)&&eq(row.shine_id,event.shineId)&&
    eq(row.scope,event.scope)&&eq(row.purpose,event.purpose)&&
    eq(row.resource_id,event.resourceId)&&eq(row.resource_category,event.resourceCategory)&&
    eq(row.decision,event.decision)&&eq(row.reason_code,event.reasonCode)&&
    eq(row.grant_id,event.grantId);
};

/** @param {{sql:any, defenceGate:any, fetchImpl?:typeof fetch}} [options] */
export function createSupabaseRuntimeAdapters({sql,defenceGate,fetchImpl=fetch}={}){
  if(typeof sql!=='function') throw new TypeError('sql must be a Postgres.js-compatible tag');
  if(typeof defenceGate!=='function') throw new TypeError('defenceGate is required');
  if(typeof fetchImpl!=='function') throw new TypeError('fetchImpl is required');

  return {
    async verifyIntegrationClient({authContext,claimedClientId}={}){
      const token=authContext?.clientToken;
      if(!token||!claimedClientId) return null;
      const tokenHash=await sha256Hex(token);
      const rows=await sql`
        select credential_id::text,client_id,client_kind
        from foundation.effective_integration_client_credentials
        where token_hash=${tokenHash}
          and effective_status='active'
        limit 1
      `;
      const row=first(rows);
      return row?{
        clientId:String(row.client_id),
        credentialId:String(row.credential_id),
        clientKind:String(row.client_kind)
      }:null;
    },

    async verifyAppCaller({authContext,claimedAppId}={}){
      const token=authContext?.appToken;
      if(!token||!claimedAppId) return null;
      const tokenHash=await sha256Hex(token);
      const rows=await sql`
        select credential_id::text, app_id
        from foundation.effective_app_credentials
        where token_hash=${tokenHash} and effective_status='active'
        limit 1
      `;
      const row=first(rows);
      return row?{appId:String(row.app_id),credentialId:String(row.credential_id)}:null;
    },

    async getAtlasFeedPublisherCapability({appId,capabilityId}={}){
      if(!appId||!capabilityId) return null;
      const rows=await sql`
        select capability_id,capability_version,app_id,capability_mode,invocation_state
        from foundation.app_capabilities
        where app_id=${appId}
          and capability_id=${capabilityId}
        limit 1
      `;
      const row=first(rows);
      return row?{
        capabilityId:String(row.capability_id),
        capabilityVersion:String(row.capability_version),
        appId:String(row.app_id),
        capabilityMode:String(row.capability_mode),
        invocationState:String(row.invocation_state)
      }:null;
    },

    async getAtlasFeedGrantContext({grantId}={}){
      if(!grantId) return null;
      const rows=await sql`
        select grant_id::text,owner_shine_id::text,app_id,scope,purpose,
               resource_id::text,resource_category,effective_status
        from foundation.effective_access_grants
        where grant_id=${grantId}::uuid
        limit 1
      `;
      const row=first(rows);
      return row?{
        grantId:String(row.grant_id),
        ownerShineId:String(row.owner_shine_id),
        appId:String(row.app_id),
        scope:String(row.scope),
        purpose:String(row.purpose),
        resourceId:row.resource_id==null?null:String(row.resource_id),
        resourceCategory:row.resource_category==null?null:String(row.resource_category),
        effectiveStatus:String(row.effective_status)
      }:null;
    },

    async persistAtlasFeedEvent({
      requestId,event,admission,eventSha256,payloadSha256,payloadSizeBytes,
      receipt,receiptSha256,persistedAt
    }={}){
      const rows=await sql`
        select foundation.persist_atlas_feed_event_v1(
          ${requestId}::uuid,
          ${JSON.stringify(event??{})}::jsonb,
          ${JSON.stringify(admission??{})}::jsonb,
          ${eventSha256},
          ${payloadSha256},
          ${JSON.stringify(receipt??{})}::jsonb,
          ${receiptSha256},
          ${persistedAt}::timestamptz
        ) as result
      `;
      return normalizeJsonObject(first(rows)?.result);
    },

    async verifyIdentity({authContext,claimedAppId}={}){
      if(!claimedAppId) return null;

      const jwt=authContext?.jwt;
      if(jwt){
        const untrusted=decodeJwtPayload(jwt);
        if(!untrusted?.iss) return null;

        const providers=await sql`
          select p.provider_id, p.kind, p.project_url, p.publishable_key
          from foundation.identity_providers p
          join foundation.app_identity_providers a on a.provider_id=p.provider_id
          where p.kind='supabase-auth'
            and p.issuer=${String(untrusted.iss)}
            and p.status='active'
            and a.app_id=${claimedAppId}
            and a.status='active'
          limit 1
        `;
        const provider=first(providers);
        if(!provider) return null;

        const verification=await fetchImpl(String(provider.project_url).replace(/\/$/,'')+'/auth/v1/user',{
          method:'GET',
          headers:{apikey:String(provider.publishable_key),Authorization:'Bearer '+jwt},
          signal:AbortSignal.timeout(10000)
        });
        if(!verification.ok) return null;

        let user;
        try{user=await verification.json()}catch{return null}
        if(!user?.id) return null;

        const rows=await sql`
          select b.shine_id::text as shine_id
          from foundation.identity_bindings b
          join foundation.shine_identities i on i.shine_id=b.shine_id
          where b.provider=${String(provider.provider_id)}
            and b.provider_subject=${String(user.id)}
            and b.verified_at is not null
            and i.account_state='active'
          limit 1
        `;
        const row=first(rows);
        return row?{
          shineId:String(row.shine_id),
          authSubject:String(user.id),
          providerId:String(provider.provider_id),
          ...(untrusted.session_id?{sessionId:String(untrusted.session_id)}:{})
        }:null;
      }

      const userToken=authContext?.userToken;
      if(typeof userToken!=='string'||userToken.length<32||userToken.length>2048) return null;

      const providers=await sql`
        select p.provider_id,p.kind,p.project_url,p.publishable_key,
               p.verification_resource,p.subject_field,p.token_header
        from foundation.identity_providers p
        join foundation.app_identity_providers a on a.provider_id=p.provider_id
        where p.kind='supabase-opaque-vault'
          and p.status='active'
          and a.app_id=${claimedAppId}
          and a.status='active'
        limit 2
      `;
      if(!Array.isArray(providers)||providers.length!==1) return null;
      const provider=providers[0];
      const subject=await sha256Hex(userToken);
      if(!subject) return null;

      const url=new URL('/rest/v1/'+String(provider.verification_resource),String(provider.project_url));
      url.search=new URLSearchParams({
        [String(provider.subject_field)]:'eq.'+subject,
        select:String(provider.subject_field),
        limit:'1'
      }).toString();

      const verification=await fetchImpl(url,{
        method:'GET',
        headers:{
          apikey:String(provider.publishable_key),
          [String(provider.token_header)]:userToken
        },
        signal:AbortSignal.timeout(10000)
      });
      if(!verification.ok) return null;

      let verifiedRows;
      try{verifiedRows=await verification.json()}catch{return null}
      if(!Array.isArray(verifiedRows)||verifiedRows.length!==1||String(verifiedRows[0]?.[provider.subject_field])!==subject) return null;

      const bindings=await sql`
        select b.shine_id::text as shine_id
        from foundation.identity_bindings b
        join foundation.shine_identities i on i.shine_id=b.shine_id
        where b.provider=${String(provider.provider_id)}
          and b.provider_subject=${subject}
          and b.verified_at is not null
          and i.account_state='active'
        limit 1
      `;
      const row=first(bindings);
      return row?{
        shineId:String(row.shine_id),
        authSubject:subject,
        providerId:String(provider.provider_id)
      }:null;
    },
    async verifyClaimSource({appId,providerId,userToken}={}){
      if(!appId||!providerId||typeof userToken!=='string'||userToken.length<32||userToken.length>2048) return null;

      const providers=await sql`
        select p.provider_id,p.kind,p.project_url,p.publishable_key,
               p.verification_resource,p.subject_field,p.token_header
        from foundation.identity_providers p
        join foundation.app_identity_providers a on a.provider_id=p.provider_id
        where p.provider_id=${providerId}
          and p.kind='supabase-opaque-vault'
          and p.status='active'
          and a.app_id=${appId}
          and a.status='active'
        limit 1
      `;
      const provider=first(providers);
      if(!provider) return null;

      const subject=await sha256Hex(userToken);
      if(!subject) return null;

      const url=new URL('/rest/v1/'+String(provider.verification_resource),String(provider.project_url));
      url.search=new URLSearchParams({
        [String(provider.subject_field)]:'eq.'+subject,
        select:String(provider.subject_field),
        limit:'1'
      }).toString();

      const verification=await fetchImpl(url,{
        method:'GET',
        headers:{
          apikey:String(provider.publishable_key),
          [String(provider.token_header)]:userToken
        },
        signal:AbortSignal.timeout(10000)
      });
      if(!verification.ok) return null;

      let rows;
      try{rows=await verification.json()}catch{return null}
      if(!Array.isArray(rows)||rows.length!==1||String(rows[0]?.[provider.subject_field])!==subject) return null;

      return {
        providerId:String(provider.provider_id),
        authSubject:subject
      };
    },

    async verifyClaimTarget({appId,providerId,jwt}={}){
      if(!appId||!providerId||typeof jwt!=='string'||!jwt) return null;
      const untrusted=decodeJwtPayload(jwt);
      if(!untrusted?.iss) return null;

      const providers=await sql`
        select p.provider_id,p.kind,p.project_url,p.publishable_key
        from foundation.identity_providers p
        join foundation.app_claim_identity_providers c
          on c.provider_id=p.provider_id
        where p.provider_id=${providerId}
          and p.kind='supabase-auth'
          and p.issuer=${String(untrusted.iss)}
          and p.status='active'
          and c.app_id=${appId}
          and c.status='active'
        limit 1
      `;
      const provider=first(providers);
      if(!provider) return null;

      const verification=await fetchImpl(String(provider.project_url).replace(/\/$/,'')+'/auth/v1/user',{
        method:'GET',
        headers:{
          apikey:String(provider.publishable_key),
          Authorization:'Bearer '+jwt
        },
        signal:AbortSignal.timeout(10000)
      });
      if(!verification.ok) return null;

      let user;
      try{user=await verification.json()}catch{return null}
      if(!user?.id) return null;

      const bindings=await sql`
        select b.shine_id::text as shine_id
        from foundation.identity_bindings b
        join foundation.shine_identities i on i.shine_id=b.shine_id
        where b.provider=${String(provider.provider_id)}
          and b.provider_subject=${String(user.id)}
          and b.verified_at is not null
          and i.account_state='active'
        limit 1
      `;
      const row=first(bindings);
      return row?{
        providerId:String(provider.provider_id),
        authSubject:String(user.id),
        shineId:String(row.shine_id)
      }:null;
    },

